  issueId: IssueId;
  fromProjectId: ProjectId;
  toProjectId: ProjectId;
  fromNumber: number;
  toNumber: number;
};

import {
  index,
  integer,
  primaryKey,
  sqliteTable,
  text,
  uniqueIndex,
} from "drizzle-orm/sqlite-core";

/**
 * Highest issue number ever issued in a project. Rows that leave (a move)
 * no longer contribute to `max(issues.number)`, so the allocator reads this
 * as well and never reissues a retired number.
 */
export const projectIssueCounters = sqliteTable(
  "project_issue_counters",
  {
    orgId: text("org_id").notNull(),
    projectId: text("project_id").notNull(),
    highWater: integer("high_water").notNull(),
  },
  (table) => [primaryKey({ columns: [table.orgId, table.projectId] })],
);

export type IssueRow = typeof issues.$inferSelect;

