/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return (row?.value ?? 0) + 1;
}

input.new_string:
/**
 * Next per-project issue number. Archived issues keep their number, and a
 * number that has left the project (a move) stays retired, so the result is
 * one past the highest number the project has ever issued.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return peekNextIssueNumber(getDb(), orgId, projectId);
}

type NumberSource = Pick<ReturnType<typeof getDb>, "select" | "run">;

function peekNextIssueNumber(
  db: Pick<NumberSource, "select">,
  orgId: OrgId,
  projectId: ProjectId,
): number {
  const issued = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(and(eq(issues.orgId, orgId), eq(issues.projectId, projectId)))
    .get();
  const counter = db
    .select({ highWater: projectIssueCounters.highWater })
    .from(projectIssueCounters)
    .where(
      and(
        eq(projectIssueCounters.orgId, orgId),
        eq(projectIssueCounters.projectId, projectId),
      ),
    )
    .get();
  return Math.max(issued?.value ?? 0, counter?.highWater ?? 0) + 1;
}

/** Remembers a number so a later `nextIssueNumber` will not issue it again. */
function rememberIssuedNumber(
  db: Pick<NumberSource, "run">,
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  db.run(sql`
    INSERT INTO project_issue_counters (org_id, project_id, high_water)
    VALUES (${orgId}, ${projectId}, ${issueNumber})
    ON CONFLICT(org_id, project_id) DO UPDATE SET
      high_water = MAX(high_water, excluded.high_water)
  `);
}

