/**
 * Moves an issue onto `toProjectId` and gives it that project's next number.
 * The number it leaves behind is retired. A same-project call writes nothing.
 */
export async function reassignIssueProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<Issue> {
  const db = getDb();
  const stamp = toIsoTimestamp(new Date());

  db.transaction((tx) => {
    const current = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) throw new Error(`Issue ${issueId} not found`);
    if (current.projectId === toProjectId) return;

    const toNumber = peekNextIssueNumber(tx, orgId, toProjectId);
    rememberIssuedNumber(tx, orgId, current.projectId as ProjectId, current.number);
    rememberIssuedNumber(tx, orgId, toProjectId, toNumber);

    const row = tx
      .update(issues)
      .set({ projectId: toProjectId, number: toNumber, updatedAt: stamp })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning({ id: issues.id })
      .get();
    if (!row) throw new Error(`Issue ${issueId} not found`);
  });

  const issue = await findIssueById(orgId, issueId);
  if (!issue) throw new Error(`Issue ${issueId} not found`);
  return issue;
}

