input.new_string:
/**
 * Moves an issue into another project of the same workspace.
 *
 * Requires `issue:update` on the issue and `issue:create` on the target, and
 * the target's per-project issue quota applies exactly as it does for
 * creation. The issue keeps every field except its project and its number,
 * which becomes the target's next number; the number it leaves is retired.
 * A move onto the project the issue is already in writes nothing and
 * publishes nothing. A cross-project move publishes `issue.moved` only.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  if (before.projectId === input.toProjectId) return before;

  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.toProjectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const moved = await issueRepo.reassignIssueProject(
    input.orgId,
    input.issueId,
    input.toProjectId,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: moved.id,
    fromProjectId: before.projectId,
    toProjectId: moved.projectId,
    fromNumber: before.number,
    toNumber: moved.number,
  });

  return moved;
}

