import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { moveIssueToProjectSchema } from "@/schemas/issue";
import { activityFilterSchema } from "@/schemas/activity";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import { registerSearchListeners, search } from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let detachActivity: () => void;
let detachSearch: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
  detachSearch = registerSearchListeners();
  tenant = await createTenant("movetemp", "free");
});

afterAll(() => {
  detachActivity();
  detachSearch();
  cleanup();
});

describe("moveIssueToProject", () => {
  it("moves, renumbers, retires, audits and reindexes", async () => {
    const target = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Other",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#111111",
      targetDate: null,
    });

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "MoveMeMarker" }),
    );
    const second = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Stays" }),
    );

    await commentRepo.insertComment({
      orgId: tenant.org.id,
      issueId: issue.id,
      authorId: tenant.userIds.member,
      body: "keep me",
      parentId: null,
      mentionedUserIds: [],
    });

    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (payload) => {
      seen.push(payload);
    });
    const created: unknown[] = [];
    const offCreated = subscribe("issue.created", (payload) => created.push(payload));
    const updated: unknown[] = [];
    const offUpdated = subscribe("issue.updated", (payload) => updated.push(payload));

    const moved = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: target.id,
    });

    expect(moved.id).toBe(issue.id);
    expect(moved.projectId).toBe(target.id);
    expect(moved.number).toBe(1);
    expect(moved.title).toBe(issue.title);
    expect(moved.status).toBe(issue.status);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      actorId: tenant.userIds.member,
      issueId: issue.id,
      fromProjectId: tenant.project.id,
      toProjectId: target.id,
      fromNumber: issue.number,
      toNumber: 1,
    });
    expect(created).toHaveLength(0);
    expect(updated).toHaveLength(0);
    off();
    offCreated();
    offUpdated();

    const same = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: target.id,
    });
    expect(same.number).toBe(moved.number);
    expect(same.updatedAt).toBe(moved.updatedAt);

    const nextSource = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    expect(nextSource).toBe(Math.max(issue.number, second.number) + 1);

    const back = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
